import{_ as l,H as e,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"25 | 可靠性基础科学：可靠性背后的运筹学和概率学","description":"","frontmatter":{},"headers":[{"level":2,"title":"概率学","slug":"概率学","link":"#概率学","children":[]},{"level":2,"title":"P(A1 ∩B1)","slug":"p-a1-∩b1","link":"#p-a1-∩b1","children":[]},{"level":2,"title":"P(B1∣A1) =","slug":"p-b1∣a1","link":"#p-b1∣a1","children":[]},{"level":2,"title":"P(A1)","slug":"p-a1","link":"#p-a1","children":[]},{"level":2,"title":"P(B1∣A1)","slug":"p-b1∣a1-1","link":"#p-b1∣a1-1","children":[]},{"level":2,"title":"P(A1 ∩B1)","slug":"p-a1-∩b1-1","link":"#p-a1-∩b1-1","children":[]},{"level":2,"title":"P(A1)","slug":"p-a1-1","link":"#p-a1-1","children":[]},{"level":2,"title":"[P(B1∣A1) > 0.99]","slug":"p-b1∣a1-0-99","link":"#p-b1∣a1-0-99","children":[]},{"level":2,"title":"[P(B1∣A1) ≪0.99]","slug":"p-b1∣a1-≪0-99","link":"#p-b1∣a1-≪0-99","children":[]},{"level":2,"title":"运筹学","slug":"运筹学","link":"#运筹学","children":[{"level":3,"title":"概率不明确风险的如何决策？","slug":"概率不明确风险的如何决策","link":"#概率不明确风险的如何决策","children":[]},{"level":3,"title":"概率明确如何决策？","slug":"概率明确如何决策","link":"#概率明确如何决策","children":[]}]},{"level":2,"title":"x","slug":"x","link":"#x","children":[]},{"level":2,"title":"(","slug":"","link":"#","children":[]},{"level":2,"title":"C)","slug":"c","link":"#c","children":[]},{"level":2,"title":"(a","slug":"a","link":"#a","children":[]},{"level":2,"title":"(x","slug":"x-1","link":"#x-1","children":[]},{"level":2,"title":"(C)","slug":"c-1","link":"#c-1","children":[]},{"level":2,"title":"∑i=1","slug":"∑i-1","link":"#∑i-1","children":[]},{"level":2,"title":"(w","slug":"w","link":"#w","children":[]},{"level":2,"title":"(max","slug":"max","link":"#max","children":[]},{"level":2,"title":"∑i=1","slug":"∑i-1-1","link":"#∑i-1-1","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SRE实践：服务可靠性案例课/25｜可靠性基础科学：可靠性背后的运筹学和概率学.md","filePath":"SRE实践：服务可靠性案例课/25｜可靠性基础科学：可靠性背后的运筹学和概率学.md","lastUpdated":1795534831000}'),s={name:"SRE实践：服务可靠性案例课/25｜可靠性基础科学：可靠性背后的运筹学和概率学.md"};function p(t,a,r,o,h,u){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="_25-可靠性基础科学-可靠性背后的运筹学和概率学" tabindex="-1">25 | 可靠性基础科学：可靠性背后的运筹学和概率学 <a class="header-anchor" href="#_25-可靠性基础科学-可靠性背后的运筹学和概率学" aria-label="Permalink to &quot;25 | 可靠性基础科学：可靠性背后的运筹学和概率学&quot;">​</a></h1><p>你好，我是白园。今天我们聊一下可靠性背后的一些基础学科——运筹学和概率学的知识。</p><h2 id="概率学" tabindex="-1">概率学 <a class="header-anchor" href="#概率学" aria-label="Permalink to &quot;概率学&quot;">​</a></h2><p>首先看下概率学相关的，在添加监控和报警的时候，我们发现服务 A 同时对外提供了多个功能，比如点赞、评论、互动等都是服务 A 同时提供的。同时还带了几十个小的功能，这个时候如果我们想配置可用性的报警，是都配置还是只配置几个重要的就行呢？ 其实这个背后就会涉及到一个概率学的知识。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25/1.png" alt=""></a></p><p>就是当 A1 发生的时候，B1 同时发生的概率是多少。如果 A1 发生的时候，B1 也同时概率超过 99%。这个时候只需要保证 A1 的可用性就行；如果 A1 发生的时候，B1 同时概率很低，那这个时候就必须添加 B1 报警。 这背后其实就是一个概率学上的分析，是否是独立事件的分析。</p><p>当 A1 发生时，B1 同时发生的概率可以通过条件概率来计算，公式如下：</p><h2 id="p-a1-∩b1" tabindex="-1">P(A1 ∩B1) <a class="header-anchor" href="#p-a1-∩b1" aria-label="Permalink to &quot;P(A1 ∩B1)&quot;">​</a></h2><h2 id="p-b1∣a1" tabindex="-1">P(B1∣A1) = <a class="header-anchor" href="#p-b1∣a1" aria-label="Permalink to &quot;P(B1∣A1) =&quot;">​</a></h2><h2 id="p-a1" tabindex="-1">P(A1) <a class="header-anchor" href="#p-a1" aria-label="Permalink to &quot;P(A1)&quot;">​</a></h2><ul><li>​</li></ul><p>这里：</p><h2 id="p-b1∣a1-1" tabindex="-1">P(B1∣A1) <a class="header-anchor" href="#p-b1∣a1-1" aria-label="Permalink to &quot;P(B1∣A1)&quot;">​</a></h2><ul><li>是在 A1 发生故障的时候 B1 发生故障的概率；</li></ul><h2 id="p-a1-∩b1-1" tabindex="-1">P(A1 ∩B1) <a class="header-anchor" href="#p-a1-∩b1-1" aria-label="Permalink to &quot;P(A1 ∩B1)&quot;">​</a></h2><ul><li>是 A1 与 B1 同时发生的概率；</li></ul><h2 id="p-a1-1" tabindex="-1">P(A1) <a class="header-anchor" href="#p-a1-1" aria-label="Permalink to &quot;P(A1)&quot;">​</a></h2><ul><li>是 A1 发生的概率。</li></ul><h2 id="p-b1∣a1-0-99" tabindex="-1">[P(B1∣A1) &gt; 0.99] <a class="header-anchor" href="#p-b1∣a1-0-99" aria-label="Permalink to &quot;[P(B1∣A1) &gt; 0.99]&quot;">​</a></h2><p>如果 A1 发生时，B1 同时发生的概率超过某个阈值，比如 99%，即</p><ul><li>这</li></ul><p>意味着在 A1 发生的情况下，B1 发生的可能性非常高，可以保证召回率大于 99%。在这种情况下，确保 A1 的可用性可能就足够了，因为 B1 的发生几乎可以被预测。</p><h2 id="p-b1∣a1-≪0-99" tabindex="-1">[P(B1∣A1) ≪0.99] <a class="header-anchor" href="#p-b1∣a1-≪0-99" aria-label="Permalink to &quot;[P(B1∣A1) ≪0.99]&quot;">​</a></h2><p>然而，如果 A1 发生时，B1 同时发生的概率很低</p><ul><li>，那么需要对 B1 也</li></ul><p>添加报警机制，避免可能的风险或损失。</p><p>这个时候就需要从部署的情况来看了，如果服务 1 同时提供 A、B 两个功能，对于可用性来说，功能 A、B 往往是同时出现问题；因为服务是部署在一起的，就不是独立事件。如果做了微服务，功能 A 由服务 1 提供；功能 B 由功能 2 提供。这个时候就是 A、B 就是一个相互独立事件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25/2.png" alt=""></a></p><p>因为在部署服务时，服务 1 同时提供功能 A 和功能 B，如果这两个功能是部署在一起的，它们可能共享相同的硬件、网络或软件环境，因此它们发生故障可能是相互关联的。在这种情况下，功能 A 和功能 B 不是独立事件，它们发生故障的概率不是通过简单的乘法规则来计算的。</p><p>当服务 1 和 2 被拆分成微服务架构，功能 A 由服务 1 提供，功能 B 由服务 2 提供，如果它们在不同的硬件、网络或软件环境中运行，那么它们发生故障的概率可以认为是独立的。</p><p>微服务架构的优势之一就是它允许服务组件独立运行和扩展，减少了单点故障的风险。如果服务 1 和 2 是完全独立的，那么一个服务的故障不太可能影响另一个服务，从而提高了整个系统的可用性和容错性。但是如果服务拆分的过细就容易陷入另外一个极端，服务数量膨胀，资源无法充分的利用。</p><p>在进行报警和监控系统的优化与整合时，应采用概率学视角来评估报警设置的必要性。具体而言，需要分析并判断是否每一类报警都确实需要被纳入监控体系，就可以从更多的视角来看待问题。</p><h2 id="运筹学" tabindex="-1">运筹学 <a class="header-anchor" href="#运筹学" aria-label="Permalink to &quot;运筹学&quot;">​</a></h2><p>在可靠性保证的工作中往往会面对很多突发状况，往往需要团队成员共同讨论和作出决策。由于缺乏明确的责任归属，决策过程中常出现犹豫不决的现象。</p><p>决策瓶颈往往源于缺乏一套坚实的理论支撑。如果我们能够依据一套科学的理论模型来指导决策，那么整个过程将变得更加客观和系统化。这种方法不仅能显著提高决策效率，还能在事后评估时，避免将责任不公正地归咎于任何个人。</p><p>这背后的理论支撑就是运筹学里面的决策论。决策的情况分两种，一种是概率不确定的风险如何决策，一种是概率明确的风险如何决策。</p><h3 id="概率不明确风险的如何决策" tabindex="-1">概率不明确风险的如何决策？ <a class="header-anchor" href="#概率不明确风险的如何决策" aria-label="Permalink to &quot;概率不明确风险的如何决策？&quot;">​</a></h3><p>我曾经遇到过一个紧急案例，机房突然接到市电供应中断的通知，目前只能依靠不太稳定的柴油发电机来维持电力供应。面对这种高风险状况，我们需要迅速做出关键决策：立即将流量迁移到其他机房，或是继续依赖可能发生故障的柴油发电机。</p><p>选择立即迁移流量虽然可能导致服务功能因其他机房的容量限制而有所降低，从而带来一些损失，但这一策略可以最大限度地规避潜在的更大风险。而如果选择留在原地不转移，一旦柴油发电机故障，我们将面临长达 1～2 小时的服务全面中断，这将带来极为严重的后果。</p><p>在这种情况下，如何决策呢？又有哪些运筹学的知识呢？在这种情况下，如何做出合理的决策至关重要。定最优策略前面临的主要挑战是柴油发电机故障的概率不明确，这给决策带来了不确定性。在这种情况下，我们可以考虑几种常见的决策原则来指导我们做出选择。</p><ul><li><p>乐观原则：有的人基于对机房可靠性的信心，选择不进行流量转移，坚持当前供电方案。</p></li><li><p>悲观原则：有的人出于对机房可能发生故障的担忧，立即执行流量转移，以避免潜在的大规模服务中断。</p></li><li><p>最小后悔原则（最小最大遗憾原则或 Savage 准则）在不确定性下做出决策，它考虑了在每种情况下可能发生的最坏结果，并试图最小化这种最坏结果的遗憾值。</p></li></ul><p>以下是使用最小后悔原则进行决策的步骤：</p><ol><li><p>确定可能的决策：在这种情况下，我们有两个决策选项，提前将流量切走和不切走，等待柴油发电机的表现。</p></li><li><p>确定可能的结果：对于每个决策，确定可能发生的结果。例如：</p></li></ol><ul><li><p>如果切走流量，可能的结果包括其他机房容量不够导致功能降级，柴油发电机正常工作，业务没有受到影响。</p></li><li><p>如果不切走流量，可能的结果包括柴油发电机正常工作，业务没有受到影响，柴油发电机故障，导致大面积服务不可用。</p></li></ul><ol start="3"><li><p>评估每个结果的遗憾值：对于每个结果，评估其遗憾值或损失。遗憾值是如果结果发生，你会感到多么后悔没有选择另一种决策。</p></li><li><p>计算每个决策的遗憾值：对于每个决策，计算在所有可能结果下的最大遗憾值。</p></li><li><p>选择具有最小最大遗憾值的决策：选择那个在最坏情况下遗憾值最小的决策。</p></li></ol><p>应用最小后悔原则之后，我们来看一下简化后的示例结果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SRE%E5%AE%9E%E8%B7%B5%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%8F%AF%E9%9D%A0%E6%80%A7%E6%A1%88%E4%BE%8B%E8%AF%BE/images/25/3.png" alt=""></a></p><p>在这个表中，遗憾值 1、2、3 和 4 需要根据实际情况进行评估。例如，如果大面积不可用的后果远比功能降级更严重，那么遗憾值 4 可能会远大于遗憾值 1。</p><p>根据上表，我们可以进行以下计算：</p><ul><li><p>决策 A 的最大遗憾值：max(遗憾值 1, 遗憾值 3)</p></li><li><p>决策 B 的最大遗憾值：max(遗憾值 2, 遗憾值 4)</p></li></ul><p>如果 max(遗憾值 1, 遗憾值 3) &lt; max(遗憾值 2, 遗憾值 4)，则选择决策 A（提前切走流量）。反之，则选择决策 B。</p><p>当你需要给老板决策的时候，你就可以利用运筹学的知识提供多个原则供老板去参考和决策，需要让老板在乐观、悲观、最小最大后悔原则直接做出判断和决策。</p><h3 id="概率明确如何决策" tabindex="-1">概率明确如何决策？ <a class="header-anchor" href="#概率明确如何决策" aria-label="Permalink to &quot;概率明确如何决策？&quot;">​</a></h3><p>如果这个柴发确定停止发电了，这个时候就是变成了概率明确的故障，针对概率明确故障这里采用的是贝叶斯原则，也就是收益最大化的原则；根据不同的机房和故障情况，给出当前损失最小的预案。</p><p>这个时候我们就可能面临多个条件，容量有限的情况如何保障最核心的业务，让损失最小。这里我们采用线性规划来实现。 当考虑到部分运行业务时，线性规划模型需要进行相应的调整，因为决策变量不再局限于 0 或 1（完全不运行或完全运行），而是可以取 0 到 1 之间的任何值，表示业务运行的程度。以下是调整后的步骤：</p><ol><li><p>定义目标函数：目标是最小化业务损失，可以通过最大化关键业务的部分或全部运行来实现。</p></li><li><p>确定决策变量：为每个业务定义决策变量，表示该业务的运行程度。</p></li></ol><h2 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to &quot;x&quot;">​</a></h2><ul><li>$$：第 i 个业务的运行程度（0 表示完全不运行，1 表示完全运行）​i</li></ul><ol start="3"><li>建立约束条件</li></ol><ul><li><p>容量约束：所有业务运行所需的资源总和不能超过机房的容量限制。</p></li><li><p>n</p></li></ul><h2 id="" tabindex="-1">( <a class="header-anchor" href="#" aria-label="Permalink to &quot;(&quot;">​</a></h2><ul><li>​ ≤</li></ul><h2 id="c" tabindex="-1">C) <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C)&quot;">​</a></h2><h2 id="a" tabindex="-1">(a <a class="header-anchor" href="#a" aria-label="Permalink to &quot;(a&quot;">​</a></h2><ul><li>​)</li></ul><h2 id="x-1" tabindex="-1">(x <a class="header-anchor" href="#x-1" aria-label="Permalink to &quot;(x&quot;">​</a></h2><ul><li>​)</li></ul><h2 id="c-1" tabindex="-1">(C) <a class="header-anchor" href="#c-1" aria-label="Permalink to &quot;(C)&quot;">​</a></h2><h2 id="∑i-1" tabindex="-1">∑i=1 <a class="header-anchor" href="#∑i-1" aria-label="Permalink to &quot;∑i=1&quot;">​</a></h2><ul><li>​ a​x，其中是第 i 个业务在运行程度下所需的资源量，是机房iiii</li></ul><p>的容量限制。</p><ul><li><p>业务依赖性约束：确保依赖于其他业务的业务至少运行到一定程度。</p></li><li><p>最小运行约束：对于关键业务，可能需要设置最小运行程度的要求。</p></li></ul><ol start="4"><li>量化业务价值：为每个业务分配一个权重，表示其对整体业务的重要性。</li></ol><h2 id="w" tabindex="-1">(w <a class="header-anchor" href="#w" aria-label="Permalink to &quot;(w&quot;">​</a></h2><ul><li>​)：第 ( i ) 个业务的权重。i</li></ul><ol start="5"><li>构建线性规划模型</li></ol><ul><li>目标函数：最大化总权重与运行程度的乘积n</li></ul><h2 id="max" tabindex="-1">(max <a class="header-anchor" href="#max" aria-label="Permalink to &quot;(max&quot;">​</a></h2><ul><li>​)</li></ul><h2 id="∑i-1-1" tabindex="-1">∑i=1 <a class="header-anchor" href="#∑i-1-1" aria-label="Permalink to &quot;∑i=1&quot;">​</a></h2><ul><li>​ w​xii约束条件：包括容量约束、业务依赖性约束和最小运行约束。</li></ul><ol start="6"><li><p>求解线性规划问题：使用适当的线性规划求解器求解上述问题。</p></li><li><p>实施解决方案：根据求解结果，调整各业务的运行程度。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你可以看一下使用 Python 的 scipy.optimize 模块进行线性规划的示例代码。</span></span>
<span class="line"><span>from scipy.optimize import linprog</span></span>
<span class="line"><span># 业务权重</span></span>
<span class="line"><span>weights = [20, 15, 10, 5]  # 假设有4个业务，不同的权重</span></span>
<span class="line"><span># 每个业务在完全运行时所需的资源量</span></span>
<span class="line"><span>full_resource_requirements = [100, 80, 60, 40]</span></span>
<span class="line"><span># 机房容量限制</span></span>
<span class="line"><span>capacity = 250</span></span>
<span class="line"><span># 目标函数系数（我们希望最大化这个值）</span></span>
<span class="line"><span>c = weights</span></span>
<span class="line"><span># 约束条件的不等式系数矩阵</span></span>
<span class="line"><span>A_ub = [[-1] * len(full_resource_requirements)]  # 资源限制</span></span>
<span class="line"><span>b_ub = [-capacity]  # 容量限制</span></span>
<span class="line"><span># 每个业务的资源需求与其运行程度的乘积</span></span>
<span class="line"><span>resource_requirements = [frr / 100 * i for frr in full_resource_requirements for</span></span>
<span class="line"><span># 更新约束条件</span></span>
<span class="line"><span>A_ub += [[req if j == i else 0 for j in range(len(resource_requirements))]</span></span>
<span class="line"><span>        for i, req in enumerate(resource_requirements)]</span></span>
<span class="line"><span># 决策变量的界限（0表示不运行，100表示完全运行）</span></span>
<span class="line"><span>x_bounds = [(0, 100) for _ in range(len(resource_requirements))]</span></span>
<span class="line"><span># 使用单纯形算法求解线性规划问题</span></span>
<span class="line"><span>res = linprog(c=c, A_ub=A_ub, b_ub=b_ub, bounds=x_bounds, method=&#39;highs&#39;)</span></span>
<span class="line"><span># 将结果转换为每个业务的运行程度</span></span>
<span class="line"><span>business_operation_levels = [res.x[i:i+100] for i in range(0, len(res.x), 100)]</span></span>
<span class="line"><span># 输出结果</span></span>
<span class="line"><span>print(f&quot;每个业务的运行程度：{business_operation_levels}&quot;)</span></span>
<span class="line"><span>print(f&quot;最大化权重总和：{-res.fun}&quot;)</span></span></code></pre></div><p>请注意，这个示例代码是一个简化的版本，实际应用中需要根据具体情况定义权重、资源需求和约束条件。此外，当业务可以部分运行时，可能需要更精细的资源分配策略，以及更复杂的模型来反映不同运行程度下的资源消耗和业务价值。小。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课我简单介绍了一下可靠性其背后蕴含的大量概率学、运筹学等知识，希望可以帮助你在日常问题中做出不同角度的思考。可靠性背后还有很多其他的知识我就不一一分享了，需要你去探索，这里我分享一些好的课程给你，周志华老师的机器学习、王焕钢老师的运筹学、保罗. 罗基的可靠性科学，如果你感兴趣的话，可以自己去读一读。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你平时还有哪些跟可靠性跟基础学科的思路和场景，欢迎分享到评论区，也欢迎你把这节课的内容分享给其他朋友。</p>`,88)])])}const b=l(s,[["render",p]]);export{d as __pageData,b as default};
